let enemiesSpawned = [false, false];
let waveReady = false;

function loadLevel() {
 return new Promise(function(resolve) {
  for (let i = 0; i < enemiesSpawned.length; i++) {
   if (!enemiesSpawned[i]) {
    enemiesSpawned[i] = true;
   }
  }
  setTimeout(function() {
   waveReady = true;
   console.log(
    `Wave is ready: ${enemiesSpawned.length} enemies spawned...`);
   resolve(waveReady);
  }, 1000);
 });
}

function spawnEnemies(isWaveReady) {
 return new Promise(function(resolve, reject) {
  if (isWaveReady) {
   setTimeout(function() {
    resolve("Enemies are active. Fight!");
   }, 1000);
  } else {
   setTimeout(function() {
    reject("Wave is not ready yet.");
   }, 1000);
  }
 });
}

function startWave() {
 return loadLevel()
 .then(function(isWaveReady) {
  return spawnEnemies(isWaveReady)
  .(function(result) {
   console.log(result);
  }).(function(error) {
   console.log(error);
  });
 });
}
startWave();

